before:
value={semanticRuntime.engine} onChange={(event) => setSemanticDraft({
                ...semanticRuntime,
                engine: event.target.value as SemanticRuntime["engine"],
              })}

value={semanticRuntime.provider} onChange={(event) => setSemanticDraft({
                ...semanticRuntime,
                provider: event.target.value as SemanticRuntime["provider"],
              })} disabled={semanticRuntime.engine !== "meilisearch_hybrid"}

aria-label="更换阅读版本" value={work.editionId} onChange={async event => {
              const version = versions.find(row => row.id === event.target.value);
              if (!version || version.id === work.editionId || !(await canLeave())) return;
              const url = version.readable_asset ? `/reader/${encodeURIComponent(version.readable_asset.id)}` : `/works/${encodeURIComponent(version.public_slug || version.id)}`;
              router.push(researchReturn && version.readable_asset ? `${url}?${new URLSearchParams({ return_to: researchReturn })}` : url);
            }}

name={`evaluation_relevance_${index}`} value={evaluationJudgments[item.id] ?? ""} onChange={(event) => {
                      const value = event.target.value;
                      setEvaluationJudgments((current) => {
                        if (value === "") {
                          const next = { ...current };
                          delete next[item.id];
                          return next;
                        }
                        return { ...current, [item.id]: Number(value) };
                      });
                    }}

id={fieldId} value={row[column.key] ?? ""} onChange={(event) => {
                        const next = [...rows];
                        next[index] = { ...row, [column.key]: event.target.value };
                        onChange(next);
                      }}
